const fs=require('node:fs'),path=require('node:path'),cp=require('node:child_process');const root=process.cwd();
const git=(cwd,...args)=>cp.execFileSync('git',args,{cwd,encoding:'utf8',stdio:['ignore','pipe','pipe']}).trim();
const repo=path.join(root,'repository'),remote=path.join(root,'remote.git'),source=path.join(root,'task-worktree');
fs.mkdirSync(path.join(repo,'src'),{recursive:true});git(repo,'init','-q','-b','develop');git(repo,'config','user.name','Fixture');git(repo,'config','user.email','fixture@example.invalid');
for(const id of ['A','B'])fs.writeFileSync(path.join(repo,'src',id+'.cjs'),'module.exports = 0;\n');
const checks=path.join(root,'.git','batch-checks.jsonl'),events=path.join(root,'.git','batch-events.jsonl');
const check="const fs=require('node:fs'),cp=require('node:child_process');const g=(...a)=>cp.execFileSync('git',a,{encoding:'utf8'}).trim();for(const id of (process.argv[2]?[process.argv[2]]:['A','B']))if(require('./src/'+id+'.cjs')!==1)throw Error('wrong task '+id);fs.appendFileSync("+JSON.stringify(checks)+",JSON.stringify({tree:g('write-tree'),head:g('rev-parse','HEAD'),worktrees:g('worktree','list','--porcelain').split('\\n').filter(x=>x.startsWith('worktree ')).length})+'\\n');";
fs.writeFileSync(path.join(repo,'check.cjs'),check);git(repo,'add','.');git(repo,'commit','-qm','chore(fixture): baseline');const base=git(repo,'rev-parse','HEAD');
git(root,'init','--bare','-q',remote);git(repo,'remote','add','origin',remote);git(repo,'push','-q','origin','HEAD:refs/heads/develop');
git(repo,'worktree','add','-q','-b','feat/ENG-P-batch',source,base);
fs.writeFileSync(path.join(root,'.git','batch-state.json'),JSON.stringify({repo,remote,source,base,checks,events}));
fs.writeFileSync(path.join(root,'linear-state.json'),JSON.stringify({'ENG-A':'In Progress','ENG-B':'Todo','ENG-P':'In Progress'}));
const receiver=path.join(remote,'hooks','record.cjs');
fs.writeFileSync(receiver,"const fs=require('node:fs');const input=fs.readFileSync(0,'utf8');for(const line of input.trim().split('\\n')){const [before,head,ref]=line.split(' ');fs.appendFileSync("+JSON.stringify(events)+",JSON.stringify({kind:'push',before,head,ref})+'\\n');}");
fs.writeFileSync(path.join(remote,'hooks','pre-receive'),'#!/bin/sh\nexec node "'+receiver.replaceAll('\\','/')+'"\n',{mode:0o755});
fs.writeFileSync(path.join(root,'linear.cjs'),"const fs=require('node:fs'),cp=require('node:child_process');const state=JSON.parse(fs.readFileSync('.git/batch-state.json'));const g=(cwd,...a)=>cp.execFileSync('git',a,{cwd,encoding:'utf8'}).trim();const id=process.argv[2],remote=g(state.remote,'rev-parse','refs/heads/develop');fs.appendFileSync(state.events,JSON.stringify({kind:'done',id,remote})+'\\n');for(const x of ['A','B'])if(!/exports\\s*=\\s*1/.test(g(state.remote,'show',remote+':src/'+x+'.cjs')))throw Error('not delivered');const statuses=JSON.parse(fs.readFileSync('linear-state.json'));if(id==='ENG-P'&&['ENG-A','ENG-B'].some(x=>statuses[x]!=='Done'))throw Error('children first');statuses[id]='Done';fs.writeFileSync('linear-state.json',JSON.stringify(statuses));");
